#include<bits/stdc++.h>
using namespace std;
#define ll long long
const int N=2e6+5;
int n,R[N],f[N][3];
ll d,x[N];
int main(){
    ios::sync_with_stdio(0);
    cin.tie(0);
    int c,t;
    cin>>c>>t;
    while(t--){
        cin>>n>>d;
        for(int i=1;i<=n;i++)cin>>x[i];
        for(int i=0;i<=n;i++)f[i][0]=f[i][1]=f[i][2]=0;
        // R[i]：从 i 一步能到的最右点（单调，双指针）
        int j=1;
        for(int i=1;i<=n;i++){
            j=max(j,i);
            while(j<n&&x[j+1]-x[i]<=d)j++;
            R[i]=j;
        }
        // 每个起点 u 的第一层是 (u,R[u]]，里面每个点方案数都是 1
        for(int i=1;i<=n;i++)if(R[i]>i)f[R[i]][0]++;
        ll ans=0;
        for(int i=1;i<=n;i++){
            int q=R[i];
            if(q==i)continue;
            int p=max(i,R[i-1]),z=i;
            if(i>=2)z=max(i,R[i-2]);
            int la=q-p;     // 下一层里恰好只有一个前驱的点数
            int lb=p-z;     // 下一层里恰好有两个前驱的点数
            ans+=1ll*f[i][0]*lb;
            ans+=1ll*f[i][2]*la;
            if(la>0){
                if(la>=2||q-i==1)f[q][0]+=f[i][0]+f[i][1];
                else f[q][1]+=f[i][0]+f[i][1];
                f[q][2]+=f[i][2];
            }else if(lb>0)f[q][2]+=f[i][0];
        }
        cout<<ans<<'\n';
    }
    return 0;
}
